<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pulse — Live Analytics</title>
<style>
:root{color-scheme:dark;--bg:#090d16;--panel:#111827;--line:#253047;--muted:#8b9bb4;--text:#f5f7fb;--green:#59e4a8;--blue:#6da8ff}*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:radial-gradient(circle at 80% 0,#17233b 0,transparent 30%),var(--bg);color:var(--text)}.shell{max-width:1280px;margin:auto;padding:32px 24px 64px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:34px}.brand{display:flex;gap:12px;align-items:center;font-weight:800;font-size:20px}.logo{width:34px;height:34px;border-radius:10px;background:linear-gradient(135deg,var(--green),var(--blue));display:grid;place-items:center;color:#071016}.live{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:13px}.dot{width:8px;height:8px;border-radius:50%;background:var(--green);box-shadow:0 0 0 5px #59e4a819}h1{margin:0;font-size:clamp(28px,4vw,44px);letter-spacing:-.04em}.intro{color:var(--muted);margin:8px 0 28px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card,.panel{background:#111827cc;border:1px solid var(--line);border-radius:18px;box-shadow:0 16px 50px #0003}.card{padding:20px}.label{color:var(--muted);font-size:13px}.value{font-size:28px;font-weight:750;margin:8px 0}.change{color:var(--green);font-size:12px}.change.down{color:#ff8080}.grid{display:grid;grid-template-columns:2fr 1fr;gap:16px;margin-top:16px}.panel{padding:22px;overflow:hidden}.panel h2{font-size:15px;margin:0 0 20px}.chart{height:260px;display:flex;align-items:flex-end;gap:5px;border-bottom:1px solid var(--line);background:repeating-linear-gradient(to bottom,transparent 0,transparent 64px,#25304755 65px)}.bar{flex:1;min-width:3px;background:linear-gradient(to top,#3974d9,var(--blue));border-radius:4px 4px 0 0;transition:height .35s;position:relative}.bar:hover:after{content:attr(data-tip);position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);background:#020617;padding:6px 8px;border-radius:6px;white-space:nowrap;font-size:11px;z-index:2}.source{display:grid;grid-template-columns:75px 1fr 36px;gap:10px;align-items:center;margin:17px 0;color:var(--muted);font-size:13px}.track{height:7px;background:#202a3b;border-radius:9px;overflow:hidden}.fill{height:100%;background:var(--green);border-radius:9px}table{width:100%;border-collapse:collapse;font-size:13px}th{color:var(--muted);font-weight:500;text-align:left}td,th{padding:13px 8px;border-bottom:1px solid #25304799}.pill{display:inline-block;padding:4px 8px;border-radius:8px;background:#253047;color:#c9d5e7}.wide{margin-top:16px}.empty{color:var(--muted);padding:30px 0;text-align:center}@media(max-width:850px){.cards{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:500px){.cards{grid-template-columns:1fr}.shell{padding:22px 14px}.hide-mobile{display:none}}
</style></head><body><main class="shell"><header><div class="brand"><div class="logo">P</div>Pulse</div><div class="live"><span class="dot"></span><span id="updated">Live data</span></div></header><h1>Your business, right now.</h1><p class="intro">Sales, traffic, clicks and operations in one live view.</p><section class="cards" id="cards"></section><section class="grid"><article class="panel"><h2>Traffic today</h2><div class="chart" id="chart"></div></article><article class="panel"><h2>Top sources</h2><div id="sources"></div></article></section><article class="panel wide"><h2>Event stream</h2><div style="overflow:auto"><table><thead><tr><th>Event</th><th>Source</th><th>Value</th><th class="hide-mobile">Time</th></tr></thead><tbody id="events"></tbody></table></div></article></main>
<script>
let state=@json($snapshot);const money=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}),number=new Intl.NumberFormat('en-US'),esc=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));function format(card){return card.format==='currency'?money.format(card.value):card.format==='percent'?card.value+'%':number.format(card.value)}function render(data){document.querySelector('#cards').innerHTML=data.cards.map(card=>`<article class="card"><div class="label">${esc(card.label)}</div><div class="value">${format(card)}</div><div class="change ${card.change<0?'down':''}">${card.change>=0?'↑':'↓'} ${Math.abs(card.change)}% vs yesterday</div></article>`).join('');const max=Math.max(...data.series.map(point=>point.traffic),1);document.querySelector('#chart').innerHTML=data.series.map(point=>`<div class="bar" style="height:${Math.max(point.traffic/max*100,2)}%" data-tip="${esc(point.label)} · ${point.traffic} visits"></div>`).join('');const entries=Object.entries(data.sources),sourceMax=Math.max(...entries.map(([,count])=>count),1);document.querySelector('#sources').innerHTML=entries.length?entries.map(([source,count])=>`<div class="source"><span>${esc(source)}</span><div class="track"><div class="fill" style="width:${count/sourceMax*100}%"></div></div><b>${count}</b></div>`).join(''):'<div class="empty">No events yet</div>';document.querySelector('#events').innerHTML=data.recent.map(event=>`<tr><td><span class="pill">${esc(event.type.replace('_',' '))}</span></td><td>${esc(event.source)}</td><td>${event.type==='sale'?money.format(event.value):number.format(event.value)}</td><td class="hide-mobile">${new Date(event.occurred_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</td></tr>`).join('');document.querySelector('#updated').textContent='Updated '+new Date(data.updated_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})}render(state);setInterval(async()=>{try{const response=await fetch('/api/dashboard');state=(await response.json()).data;render(state)}catch(error){document.querySelector('#updated').textContent='Reconnecting…'}},5000);
</script></body></html>
